#include "bsp/native_renderer_resolution_enumeration.hpp"
#include "bsp/singleton_lifetime.hpp"
#include "native_renderer_resolution_reference.hpp"
#include <Windows.h>
#include <d3d9.h>
#include <array>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <stdexcept>

namespace {
using Word=std::uint32_t;
void require(bool ok,const char* message) { if(!ok) throw std::runtime_error(message); }
Word load(const void* base,Word offset=0) { Word value; std::memcpy(&value,static_cast<const unsigned char*>(base)+offset,4); return value; }
void store(void* base,Word offset,Word value) { std::memcpy(static_cast<unsigned char*>(base)+offset,&value,4); }
void* ptr(Word value) { return reinterpret_cast<void*>(value); }
Word addr(const void* value) { return reinterpret_cast<Word>(value); }
struct Pair { Word width,height; bool operator==(const Pair&) const=default; };
static_assert(sizeof(Pair)==8);
struct Renderer {
    alignas(4) std::array<unsigned char,0x1a00> bytes;
    Renderer() { bytes.fill(0xa5); std::memset(bytes.data()+0x1c,0,12); }
    void* raw() { return bytes.data(); }
    void set_api(void* value) { store(raw(),0x1990,addr(value)); }
    void initial_pairs() {
        void* data=bsp::singleton_lifetime_allocate({bsp::SingletonAllocationKind::object,16,16});
        const Pair rows[]={{1920,1080},{800,600}}; std::memcpy(data,rows,16);
        store(raw(),0x1c,addr(data)); store(raw(),0x20,2); store(raw(),0x24,2);
    }
    void guards() {
        for(std::size_t i=0;i<bytes.size();++i) {
            if((i>=0x1c&&i<0x28)||(i>=0x1990&&i<0x1994)||(i>=0x19dc&&i<0x19e0)) continue;
            require(bytes[i]==0xa5,"unrelated renderer byte changed");
        }
    }
    ~Renderer() { bsp::singleton_lifetime_free(ptr(load(raw(),0x1c))); }
};
void* __cdecl allocate_original(Word bytes) {
    return bsp::singleton_lifetime_allocate({bsp::SingletonAllocationKind::object,bytes,bytes});
}
void __cdecl free_original(void* value) noexcept { bsp::singleton_lifetime_free(value); }
using Comparator=int (__cdecl*)(const void*,const void*);
unsigned original_sorts=0;
void __cdecl sort_original(void* base,std::size_t count,std::size_t width,Comparator comparator) {
    require(width==8,"qsort row size"); ++original_sorts; std::qsort(base,count,width,comparator);
}
using OriginalEnumerate=void (__fastcall*)(void*);
using Find=std::int32_t (__fastcall*)(const void*,Word,const void*);
class Original {
    void* code_; std::size_t size_;
public:
    template<std::size_t N> explicit Original(const unsigned char (&bytes)[N]):
        code_(VirtualAlloc(nullptr,N,MEM_COMMIT|MEM_RESERVE,PAGE_READWRITE)),size_(N) {
        require(code_!=nullptr,"VirtualAlloc"); std::memcpy(code_,bytes,N);
    }
    ~Original(){VirtualFree(code_,0,MEM_RELEASE);}
    void* pointer() const { return code_; }
    template<class F> void call(std::size_t offset,F function) {
        auto* p=static_cast<unsigned char*>(code_); require(p[offset]==0xe8,"CALL relocation");
        const Word displacement=static_cast<Word>(reinterpret_cast<std::uintptr_t>(function)-reinterpret_cast<std::uintptr_t>(p+offset+5));
        std::memcpy(p+offset+1,&displacement,4);
    }
    void comparator(std::size_t offset,void* function) {
        auto* p=static_cast<unsigned char*>(code_); require(p[offset]==0x68,"PUSH comparator relocation");
        const Word value=addr(function); std::memcpy(p+offset+1,&value,4);
    }
    void finish() {
        DWORD previous; require(VirtualProtect(code_,size_,PAGE_EXECUTE_READ,&previous)!=0,"VirtualProtect");
        require(FlushInstructionCache(GetCurrentProcess(),code_,size_)!=0,"FlushInstructionCache");
    }
};
struct Snapshot {
    std::vector<Pair> pairs; Word capacity,opaque;
    bool operator==(const Snapshot&) const=default;
};
Snapshot snapshot(Renderer& renderer) {
    renderer.guards(); const Word count=load(renderer.raw(),0x20);
    const auto* data=static_cast<const Pair*>(ptr(load(renderer.raw(),0x1c)));
    Snapshot result{{},load(renderer.raw(),0x24),load(renderer.raw(),0x19dc)};
    if(count) result.pairs.assign(data,data+count);
    return result;
}
struct Script;
struct ScriptApi { Word* table; Script* script; Word id; };
struct Script {
    Renderer& renderer; std::array<Word,8> table{};
    ScriptApi initial{table.data(),this,0},first{table.data(),this,1},second{table.data(),this,2};
    unsigned count_calls=0; std::vector<Word> calls;
};
Word __stdcall mode_count(void* opaque,Word adapter,Word format) {
    auto& api=*static_cast<ScriptApi*>(opaque); auto& s=*api.script;
    require(api.id==0&&adapter==0&&format==0x16,"count actual COM arguments");
    require(load(s.renderer.raw(),0x19dc)==0,"opaque clear before count dispatch");
    ++s.count_calls; s.renderer.set_api(&s.first); return 7;
}
std::int32_t __stdcall enum_mode(void* opaque,Word adapter,Word format,Word index,void* mode) {
    auto& api=*static_cast<ScriptApi*>(opaque); auto& s=*api.script;
    require(adapter==0&&format==0x16&&index==s.calls.size(),"enumeration captured count/index/arguments");
    require(api.id==(index<2?1u:2u),"current COM interface was not reloaded"); s.calls.push_back(api.id);
    switch(index) {
    case 0:
        store(mode,0,1024); store(mode,4,768); store(mode,8,60); store(mode,12,0x16);
        return static_cast<std::int32_t>(0x80004005u);
    case 1:
        store(mode,0,1280); s.renderer.set_api(&s.second); return 1;
    case 2: store(mode,4,720); return 0;
    case 3: store(mode,0,800); store(mode,4,600); return 0;
    case 4: {
        store(mode,0,639); store(mode,4,999);
        auto* rows=static_cast<Pair*>(ptr(load(s.renderer.raw(),0x1c)));
        const Word count=load(s.renderer.raw(),0x20);
        require(count==3&&load(s.renderer.raw(),0x24)==4,"append publication before COM reentry");
        rows[count]={1366,768}; store(s.renderer.raw(),0x20,count+1); return 0;
    }
    case 5: store(mode,0,1920); store(mode,4,1080); store(s.renderer.raw(),0x19dc,0x1234); return 0;
    case 6: store(mode,0,640); store(mode,4,480); return 0;
    default: throw std::runtime_error("unexpected extra enumeration");
    }
}
Snapshot scripted(OriginalEnumerate original,bool use_original) {
    Renderer renderer; renderer.initial_pairs(); Script script{renderer};
    script.table[6]=reinterpret_cast<Word>(&mode_count); script.table[7]=reinterpret_cast<Word>(&enum_mode);
    renderer.set_api(&script.initial); Word scratch[4]={0xdddddddd,0xcccccccc,0xbbbbbbbb,0xaaaaaaaa};
    if(use_original) original(renderer.raw());
    else bsp::enumerate_native_renderer_resolutions_00b27d80(renderer.raw(),scratch);
    require(script.count_calls==1&&script.calls.size()==7,"single captured mode count");
    auto result=snapshot(renderer);
    const std::vector<Pair> expected{{640,480},{800,600},{1280,720},{1366,768},{1920,1080}};
    require(result.pairs==expected&&result.capacity==8&&result.opaque==0x1234,"scripted native postimages");
    if(!use_original) require(scratch[0]==640&&scratch[1]==480&&scratch[2]==60&&scratch[3]==0x16,"retained mode scratch writes");
    return result;
}
Snapshot real_modes(OriginalEnumerate original,IDirect3D9* api,bool use_original) {
    Renderer renderer; renderer.set_api(api); Word scratch[4]={640,480,0x9876,0x5432};
    if(use_original) original(renderer.raw());
    else bsp::enumerate_native_renderer_resolutions_00b27d80(renderer.raw(),scratch);
    return snapshot(renderer);
}
void module_record(const wchar_t* name,HMODULE module,const char* category) {
    if(!module) { std::printf("UNLOADED_RUNTIME|%ls\n",name); return; }
    wchar_t reported[1024],canonical[1024];
    const DWORD n=GetModuleFileNameW(module,reported,1024); require(n&&n<1024,"module path");
    HANDLE file=CreateFileW(reported,GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
    require(file!=INVALID_HANDLE_VALUE,"module file");
    const DWORD m=GetFinalPathNameByHandleW(file,canonical,1024,FILE_NAME_NORMALIZED); CloseHandle(file); require(m&&m<1024,"canonical module file");
    const auto* bytes=reinterpret_cast<const unsigned char*>(module);
    const auto* dos=reinterpret_cast<const IMAGE_DOS_HEADER*>(bytes);
    const auto* nt=reinterpret_cast<const IMAGE_NT_HEADERS32*>(bytes+dos->e_lfanew);
    require(nt->FileHeader.Machine==IMAGE_FILE_MACHINE_I386,"loaded machine");
    std::printf("%s|%ls|%ls|%ls|%04x\n",category,name,reported,canonical,static_cast<unsigned>(nt->FileHeader.Machine));
}
void provider_record(const wchar_t* role,void* function) {
    HMODULE module{};
    require(GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS|GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,reinterpret_cast<LPCWSTR>(function),&module)!=0,"COM provider module");
    std::printf("PROVIDER_ADDRESS|%ls|%08x\n",role,addr(function));
    module_record(role,module,"LOADED_PROVIDER");
}
void runtime_records(IDirect3D9* api) {
    for(const auto* name:{L"ucrtbase.dll",L"vcruntime140.dll",L"msvcp140.dll",L"vcruntime140_1.dll",L"d3d9.dll"}) module_record(name,GetModuleHandleW(name),"LOADED_RUNTIME");
    void* table=ptr(load(api));
    provider_record(L"IDirect3D9.GetAdapterModeCount",ptr(load(table,0x18)));
    provider_record(L"IDirect3D9.EnumAdapterModes",ptr(load(table,0x1c)));
}
}
int main() {
    try {
        Original search(original_008d46c0),reserve(original_008d4750),compare(original_00b1ffd0),enumerate(original_00b27d80);
        search.finish(); compare.finish(); reserve.call(0x20,&allocate_original); reserve.call(0x55,&free_original); reserve.finish();
        enumerate.call(0x86,search.pointer()); enumerate.call(0xa7,reserve.pointer()); enumerate.call(0xe8,&sort_original); enumerate.comparator(0xdf,compare.pointer()); enumerate.finish();
        auto original=reinterpret_cast<OriginalEnumerate>(enumerate.pointer());
        require(scripted(original,true)==scripted(original,false),"scripted original/source mismatch");
        const Word empty[3]{};
        require(reinterpret_cast<Find>(search.pointer())(empty,0,nullptr)==bsp::find_native_resolution_pair_008d46c0(empty,0,nullptr),"empty search no key read");
        const Pair left{0x80000000u,1},right{0,9};
        require(reinterpret_cast<Comparator>(compare.pointer())(&left,&right)==bsp::compare_native_resolution_pairs_00b1ffd0(&left,&right),"wrapped raw comparator");
        IDirect3D9* api=Direct3DCreate9(D3D_SDK_VERSION); require(api!=nullptr,"Direct3DCreate9");
        const auto native=real_modes(original,api,true); const auto source=real_modes(original,api,false);
        require(native==source,"real D3D9 original/source mismatch");
        std::printf("REAL_D3D9|unique_pairs=%u|capacity=%u|adapters=%u\n",static_cast<unsigned>(source.pairs.size()),source.capacity,api->GetAdapterCount());
        runtime_records(api); api->Release();
        require(original_sorts==2,"native unconditional qsort calls");
        std::puts("PASS: complete original resolution chain equals actual source for scripted COM reentry/preimages and real D3D9 modes; raw helper edges pass");
        return 0;
    } catch(const std::exception& error) { std::fprintf(stderr,"FAIL: %s\n",error.what()); return 1; }
}

